using System;
using System.IO;
using System.Linq;
using System.Drawing;
using System.Windows.Forms;
using System.Diagnostics;
using System.Collections.Generic;
using System.Runtime.InteropServices;

namespace CrossHermit {
 public sealed class LaunchPlan {public string mode,launcher,arguments,working_directory;public int code_page;public bool game_started=false,file_picker_required=false,disc_required=false;}
 public static class LauncherProgram {
  [DllImport("kernel32.dll")]static extern uint GetACP();
  [DllImport("user32.dll")]static extern bool SetProcessDPIAware();
  public static LaunchPlan Locale(string root,int cp){string exe=Path.Combine(root,"Cross Hermit.exe");if(!File.Exists(exe))throw new IOException("The game executable is missing.");var p=new LaunchPlan {code_page=cp,mode=cp==932?"direct":"bundled",working_directory=root,launcher=exe,arguments=""};if(cp!=932){string support=Path.Combine(root,"EnglishPatch");var manifest=Core.Read(Path.Combine(support,"locale-bundle.json"));foreach(var entry in (System.Collections.IEnumerable)manifest["runtime_files"]){var r=(Dictionary<string,object>)entry;string f=Core.Child(root,Convert.ToString(r["path"]));if(!File.Exists(f)||Core.Hash(f)!=Convert.ToString(r["sha256"]))throw new IOException("Bundled Japanese compatibility files are missing or changed. Reinstall the English patch.");}if(!File.Exists(exe+".le.config"))throw new IOException("The Japanese compatibility profile is missing.");p.launcher=Path.Combine(support,@"LocaleEmulator\LEProc.exe");p.arguments="-run "+Core.Quote(exe);}return p;}
  public static void StartGame(string root,Settings s,string desktop){Core.ValidateRoot(root);Core.AssertGameClosed();string option=Path.Combine(root,"Option.bin");if(!File.Exists(option)||new FileInfo(option).Length!=40)throw new IOException("Game settings are missing or damaged. Reinstall using English setup.");foreach(string n in new[]{"dgVoodoo.conf","CrossHermitUI.ini"})if(!File.Exists(Path.Combine(root,n)))File.Copy(Path.Combine(root,"EnglishPatch/Defaults",n),Path.Combine(root,n));LaunchPlan p=Locale(root,(int)GetACP());s.Apply(root,desktop);s.Save(Path.Combine(root,"EnglishPatch/settings.json"));Core.RegisterPaths(root);Process.Start(new ProcessStartInfo(p.launcher,p.arguments){WorkingDirectory=root,UseShellExecute=false});}
  [STAThread]public static int Main(string[] a){try{SetProcessDPIAware();Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);string root=AppDomain.CurrentDomain.BaseDirectory.TrimEnd('\\');bool test=Core.Has(a,"--plan")||Core.Has(a,"--apply-test")||Core.Has(a,"--preview");if(test||Core.Has(a,"--update-host"))root=Core.Full(Core.Arg(a,"--root",root));string desktop=Screen.PrimaryScreen.Bounds.Width+"x"+Screen.PrimaryScreen.Bounds.Height;desktop=Core.Arg(a,"--desktop",desktop);
   if(Core.Has(a,"--update-host")){Core.ValidateRoot(root);Application.Run(new UpdateHost(root,Core.Arg(a,"--version",""),Int32.Parse(Core.Arg(a,"--wait-pid","0"))));return 0;}
   string settingsPath=Path.Combine(root,"EnglishPatch/settings.json");Settings s;string status="Settings are ready.";try{s=Settings.Load(settingsPath);}catch(Exception e){s=new Settings();status="Saved preferences could not be read. Defaults are shown. "+e.Message;}
   if(Core.Has(a,"--plan")){var p=new {version=Core.InstalledVersion(root),launcher_version=Core.Version,settings=s,locale=Locale(root,Int32.Parse(Core.Arg(a,"--code-page",GetACP().ToString()))),game_started=false,preferences_written=false};string result=Core.Arg(a,"--result",null);if(result!=null)Core.Write(result,p);else Console.WriteLine(Core.Json.Serialize(p));return 0;}
   if(Core.Has(a,"--apply-test")){s.Apply(root,desktop);Core.Write(Core.Arg(a,"--result",Path.Combine(root,"apply-result.json")),new {passed=true,game_started=false});return 0;}
   if(!test&&!Core.Has(a,"--settings")&&!s.showOnLaunch){try{StartGame(root,s,desktop);return 0;}catch(Exception e){status=e.Message;}}
   using(var form=new LauncherForm(root,s,desktop,status)){if(Core.Has(a,"--preview")){form.Preview(Core.Arg(a,"--preview",null));return 0;}Application.Run(form);}return 0;
  }catch(Exception e){string result=Core.Arg(a,"--result",null);if(result!=null)Core.Write(result,new {passed=false,error=e.Message,game_started=false});else MessageBox.Show(e.Message,"Cross Hermit English",MessageBoxButtons.OK,MessageBoxIcon.Error);return 1;}}
 }
 public sealed class LauncherForm:Form {
  string root,desktop;Settings settings;bool ready,busy,handoff;string available="",jobFolder;Process job;Timer timer=new Timer();
  ComboBox mode=new ComboBox(),resolution=new ComboBox(),battle=new ComboBox();CheckBox show=new CheckBox();Label status=new Label(),version=new Label();Button update=new Button(),play=new Button(),close=new Button(),defaults=new Button();List<string> resolutions;
  public LauncherForm(string folder,Settings value,string screen,string initial){root=folder;settings=value;desktop=screen;Text="Cross Hermit Settings";Font=new Font("Segoe UI",9);AutoScaleDimensions=new SizeF(7,15);AutoScaleMode=AutoScaleMode.Font;ClientSize=new Size(660,374);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;StartPosition=FormStartPosition.CenterScreen;var display=new GroupBox {Text="Display"};Add(display,this,12,12,438,196);var guides=new GroupBox {Text="Reference guides"};Add(guides,this,462,12,186,196);
   string[] labels={"Display mode:","Resolution:","Battlefield layout:"};ComboBox[] combos={mode,resolution,battle};for(int i=0;i<3;i++){Add(new Label {Text=labels[i]},display,14,30+42*i,112,22);combos[i].DropDownStyle=ComboBoxStyle.DropDownList;Add(combos[i],display,140,26+42*i,282,26);combos[i].SelectedIndexChanged+=(s,e)=>SaveControls();}
   mode.Items.AddRange(new object[]{"Borderless fullscreen","Windowed"});battle.Items.AddRange(new object[]{"16:9 widescreen","Classic 4:3"});resolutions=new[]{"desktop","1280x720","1600x900","1920x1080","2560x1440","3840x2160",desktop,settings.resolution}.Distinct().ToList();foreach(string r in resolutions)resolution.Items.Add(r=="desktop"?"Desktop ("+desktop.Replace("x"," \u00d7 ")+")":r.Replace("x"," \u00d7 "));
   Add(new Label {Text="Widescreen shows more terrain without stretching characters.",ForeColor=SystemColors.GrayText},display,14,156,410,30);Guide(guides,"Skills",26,"skill-guide-0.1.211");Guide(guides,"Classes & upgrades",68,"class-guide-0.1.258");version.Text="Installed version: "+Core.InstalledVersion(root);Add(version,this,16,220,414,26);update.Text="Check for updates";Add(update,this,462,216,186,30);update.Click+=(s,e)=>UpdateClick();show.Text="Show these settings before launching";Add(show,this,16,260,430,26);show.CheckedChanged+=(s,e)=>SaveControls();status.Text=initial;status.AutoEllipsis=true;Add(status,this,16,292,630,34);
   defaults.Text="Restore Defaults";play.Text="Play";close.Text="Close";Add(defaults,this,318,332,120,30);Add(play,this,450,332,90,30);Add(close,this,552,332,96,30);AcceptButton=play;CancelButton=close;close.DialogResult=DialogResult.Cancel;close.Click+=(s,e)=>Close();defaults.Click+=(s,e)=>{settings=new Settings();SetControls();SaveControls();};play.Click+=(s,e)=>{try{LauncherProgram.StartGame(root,settings,desktop);Close();}catch(Exception x){status.Text=x.Message;}};FormClosing+=(s,e)=>{if(busy&&!handoff){e.Cancel=true;status.Text="Please wait for the update check to finish.";}};timer.Interval=200;timer.Tick+=(s,e)=>CheckFinished();SetControls();
  }
  static void Add(Control c,Control p,int x,int y,int w,int h){c.SetBounds(x,y,w,h);p.Controls.Add(c);var b=c as Button;if(b!=null)b.UseVisualStyleBackColor=true;}
  void Guide(Control group,string title,int y,string folder){var b=new Button {Text=title,UseMnemonic=false};Add(b,group,14,y,158,29);b.Click+=(s,e)=>{try{Process.Start(new ProcessStartInfo(Path.Combine(root,"EnglishPatch/Guides",folder,"index.html")){UseShellExecute=true});}catch(Exception x){status.Text=x.Message;}};}
  void SetControls(){ready=false;mode.SelectedIndex=settings.displayMode=="windowed"?1:0;resolution.SelectedIndex=resolutions.IndexOf(settings.resolution);battle.SelectedIndex=settings.battlefield=="classic"?1:0;show.Checked=settings.showOnLaunch;ready=true;}
  void SaveControls(){if(!ready||mode.SelectedIndex<0||resolution.SelectedIndex<0||battle.SelectedIndex<0)return;try{settings.displayMode=mode.SelectedIndex==1?"windowed":"borderless";settings.resolution=resolutions[resolution.SelectedIndex];settings.battlefield=battle.SelectedIndex==1?"classic":"wide";settings.showOnLaunch=show.Checked;settings.Save(Path.Combine(root,"EnglishPatch/settings.json"));status.Text="Preferences saved. Applied when you press Play.";}catch(Exception e){status.Text=e.Message;}}
  void Busy(bool value){busy=value;foreach(Control c in new Control[]{update,play,close,defaults,mode,resolution,battle,show})c.Enabled=!value;}
  void UpdateClick(){if(busy)return;try{if(available!=""){Core.AssertGameClosed();string temp=Path.Combine(Path.GetTempPath(),"CH-update-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);string host=Path.Combine(temp,"Update.exe");File.Copy(Application.ExecutablePath,host);Process.Start(new ProcessStartInfo(host,"--update-host --root "+Core.Quote(root)+" --version "+Core.Quote(available)+" --wait-pid "+Process.GetCurrentProcess().Id){UseShellExecute=false,CreateNoWindow=true});handoff=true;Close();return;}jobFolder=Path.Combine(Path.GetTempPath(),"CH-check-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(jobFolder);string args="-NoProfile -ExecutionPolicy Bypass -File "+Core.Quote(Path.Combine(root,"EnglishPatch/Update-Game.ps1"))+" -Action Check -GameFolder "+Core.Quote(root)+" -ResultFile "+Core.Quote(Path.Combine(jobFolder,"result.json"));job=Core.Hidden(Core.PowerShell,args,root);Busy(true);status.Text="Checking GitHub for updates...";timer.Start();}catch(Exception e){Busy(false);status.Text=e.Message;}}
  void CheckFinished(){if(job==null||!job.HasExited)return;timer.Stop();try{var r=Core.Read(Path.Combine(jobFolder,"result.json"));status.Text=Convert.ToString(r["message"]);available=Convert.ToString(r["state"])=="available"?Convert.ToString(r["version"]):"";update.Text=available==""?"Check for updates":"Update to "+available;}catch(Exception e){status.Text=e.Message;available="";}finally{job.Dispose();job=null;Busy(false);CleanJob();}}
  void CleanJob(){if(jobFolder==null)return;foreach(string n in new[]{"result.json"}){string f=Path.Combine(jobFolder,n);if(File.Exists(f))File.Delete(f);}if(Directory.Exists(jobFolder)&&Directory.GetFileSystemEntries(jobFolder).Length==0)Directory.Delete(jobFolder);jobFolder=null;}
  public void Preview(string path){ShowInTaskbar=false;var handle=Handle;foreach(Control c in Controls)CreateHandles(c);PerformLayout();using(var bitmap=new Bitmap(Width,Height)){DrawToBitmap(bitmap,new Rectangle(0,0,Width,Height));bitmap.Save(path,System.Drawing.Imaging.ImageFormat.Png);}}
  static void CreateHandles(Control c){var h=c.Handle;foreach(Control q in c.Controls)CreateHandles(q);}
  protected override void Dispose(bool disposing){if(disposing){timer.Dispose();if(job!=null)job.Dispose();}base.Dispose(disposing);}
 }
 public sealed class UpdateHost:Form {
  string root,version,folder;int parent;Label status=new Label();Button close=new Button();Timer timer=new Timer();Process worker;bool done;
  public UpdateHost(string r,string v,int pid){root=r;version=v;parent=pid;Text="Cross Hermit Update";Font=new Font("Segoe UI",10);ClientSize=new Size(520,160);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;StartPosition=FormStartPosition.CenterScreen;status.SetBounds(18,18,484,85);status.Text="Installing version "+v+". Please wait...";Controls.Add(status);close.Text="Close";close.SetBounds(400,115,100,30);close.Enabled=false;close.Click+=(s,e)=>Close();Controls.Add(close);FormClosing+=(s,e)=>{if(!done)e.Cancel=true;};Shown+=(s,e)=>Begin();timer.Interval=250;timer.Tick+=(s,e)=>Poll();}
  void Begin(){try{if(parent>0){try{using(var p=Process.GetProcessById(parent))if(!p.WaitForExit(30000))throw new IOException("Close the launcher and check for updates again.");}catch(ArgumentException){}}Core.AssertGameClosed();folder=Path.Combine(Path.GetTempPath(),"CH-install-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string args="-NoProfile -ExecutionPolicy Bypass -File "+Core.Quote(Path.Combine(root,"EnglishPatch/Update-Game.ps1"))+" -Action Install -GameFolder "+Core.Quote(root)+" -ExpectedVersion "+Core.Quote(version)+" -ResultFile "+Core.Quote(Path.Combine(folder,"result.json"));worker=Core.Hidden(Core.PowerShell,args,root);timer.Start();}catch(Exception e){Finish(e.Message,false);}}
  void Poll(){if(!worker.HasExited)return;timer.Stop();try{var result=Core.Read(Path.Combine(folder,"result.json"));Finish(Convert.ToString(result["message"]),Convert.ToString(result["state"])=="installed");}catch(Exception e){Finish(e.Message,false);}finally{worker.Dispose();}}
  void Finish(string text,bool installed){done=true;status.Text=text;if(installed)status.Text+=" Reopen Launcher.exe to continue.";close.Enabled=true;}
  protected override void Dispose(bool d){if(d)timer.Dispose();base.Dispose(d);}
 }
}
